const std=@import("std");const F=@import("model/machine.zig").Fixture;const c=@import("model/machine.zig").c;const m=@cImport({@cInclude("hd_file_model.h");@cInclude("uci_model.h");});extern fn helper_seed_open(?*anyopaque)void;const a=std.testing.allocator;
const Lane=struct{f:F,s:std.StringHashMap(u16),data:[]u8,fn init(enable:bool,size:usize)!Lane{var f=try F.init();errdefer f.deinit();const b=try std.Io.Dir.cwd().readFileAlloc(std.Options.debug_io,"build/hd_close_reopen/close-reopen.prg",a,.limited(16384));defer a.free(b);c.dos64_load(f.machine,0x801,b[2..].ptr,b.len-2);var symbols=std.StringHashMap(u16).init(a);const labels=try std.Io.Dir.cwd().readFileAlloc(std.Options.debug_io,"build/hd_close_reopen/close-reopen.labels",a,.limited(100000));defer a.free(labels);var lines=std.mem.splitScalar(u8,labels,'\n');while(lines.next())|line|{var words=std.mem.tokenizeAny(u8,line," \r\t");if(!std.mem.eql(u8,words.next() orelse continue,"al"))continue;const addr=words.next() orelse continue;const name=words.next() orelse continue;if(symbols.contains(name[1..]))continue;try symbols.put(try a.dupe(u8,name[1..]),try std.fmt.parseInt(u16,addr,16));}
 const cfg=symbols.get("helper_config").?;f.poke(cfg+4,if(enable)0xa5 else 0);const path="/usb1/DOS64_TEST/helper-case/DOSHD.IMG\x00";f.poke(cfg+5,path.len);for(path,0..)|v,i|f.poke(cfg+6+@as(u16,@intCast(i)),v);m.dos64_uci_model_enable(f.machine,0xdf1c,3,0xc9);const data=try a.alloc(u8,size);for(data,0..)|*v,i|v.*=@truncate(i*19+(i>>16));m.hd_model_source(f.machine,data.ptr,data.len);m.hd_model_path(f.machine,path.ptr,path.len-1);helper_seed_open(f.machine);c.dos64_cia_clock_enable(f.machine);c.dos64_cia_clock_step(f.machine,1);return .{.f=f,.s=symbols,.data=data};}
 fn deinit(self:*Lane)void{var keys=self.s.keyIterator();while(keys.next())|k|a.free(k.*);self.s.deinit();self.f.deinit();a.free(self.data);}
 fn run(self:*Lane,entry:[]const u8,stop:[]const u8)!void{c.dos64_set_regs(self.f.machine,.{.pc=self.s.get(entry).?,.sp=0xff,.a=0,.x=0,.y=0,.p=0x24,.cycles=0,.instructions=0});const r=c.dos64_run(self.f.machine,self.s.get(stop).?,100_000_000);if(r.status!=c.DOS64_RUN_RETURNED){std.debug.print("helper status={d}pc={x}mail={x}/{x}/{x}\n",.{r.status,r.regs.pc,self.f.peek(0x6004),self.f.peek(0x6005),self.f.peek(0x6006)});return error.HelperRun;}}
 fn operation(self:*Lane,op:u8,off:u32,count:u16,stop:[]const u8)!void{self.f.poke(0x600a,op);self.f.poke(0x600b,@truncate(count));self.f.poke(0x600c,@truncate(count>>8));for(0..4)|i|self.f.poke(0x600d+@as(u16,@intCast(i)),@truncate(off>>@as(u5,@intCast(8*i))));self.f.poke(0x6004,0x47);try self.run("helper_ready",stop);}
};
test "disabled helper performs no command"{var l=try Lane.init(false,20*1024*1024);defer l.deinit();try l.run("helper_entry","helper_idle");try std.testing.expectEqual(@as(u32,0),m.hd_model_commands(l.f.machine));}
test "actual close reopen INFO selected reads above16M short EOF and final close"{var l=try Lane.init(true,20*1024*1024);defer l.deinit();try l.run("helper_entry","helper_ready");try std.testing.expectEqual(@as(u8,0x11),l.f.peek(0x6004));try std.testing.expectEqual(@as(u8,7),l.f.peek(0x6017)&7);try std.testing.expectEqual(@as(u8,5),l.f.peek(0x6018)&7);try std.testing.expectEqual(@as(u8,4),l.f.peek(0x6019)&12);try std.testing.expectEqual(@as(u32,1),m.hd_model_count_op(l.f.machine,3));try std.testing.expectEqual(@as(u32,1),m.hd_model_count_op(l.f.machine,2));for([_]u32{0,0x1000000,20*1024*1024-1,20*1024*1024})|off|{try l.operation(1,off,512,"helper_read_done");const n=@min(@as(usize,512),l.data.len-off);try std.testing.expectEqual(@as(u16,@intCast(n)),l.f.word(0x6011));for(0..n)|i|try std.testing.expectEqual(l.data[off+i],l.f.peek(0x6200+@as(u16,@intCast(i))));}
 try l.operation(2,0,0,"helper_idle");try std.testing.expectEqual(@as(u8,0xa5),l.f.peek(0x6004));try std.testing.expectEqual(@as(u8,0),l.f.peek(0x6008));try std.testing.expectEqual(@as(u8,0xa5),l.f.peek(0x601f));try std.testing.expectEqual(@as(u32,0),m.hd_model_count_op(l.f.machine,5));}
